def fmt(v,dec=2):return '—' if v is None or (isinstance(v,float) and not np.isfinite(v)) else f'{v:,.{dec}f}'
def streak(v):
 a=b=ma=mb=0
 for z in v:a=a+1 if z>0 else 0;b=b+1 if z<0 else 0;ma=max(ma,a);mb=max(mb,b)
 return ma,mb
def main():
 raw=pd.read_csv(ROOT/'hourly-summary.csv');audit=json.loads((ROOT/'AUDIT.json').read_text());native=json.loads((ROOT/'NATIVE SUMMARY.json').read_text());normalized=[]
 for r in native:
  name=r['manifest']['window'];d=pd.DataFrame(json.loads((ROOT/'native'/name/'trades.json').read_text()));v=d.net_profit.to_numpy();gp=v[v>0].sum();gl=-v[v<0].sum();start=r['manifest']['start'].replace('.','-');end=r['manifest']['end'].replace('.','-')
  calendar=pd.bdate_range(start,pd.Timestamp(end)-pd.Timedelta(days=1)).strftime('%Y-%m-%d');daily=d.assign(date=d.close_time.str[:10]).groupby('date').net_profit.sum().reindex(calendar,fill_value=0).to_numpy();sh=daily.mean()/daily.std(ddof=1)*np.sqrt(252)
  mw,ml=streak(v);months=(pd.Timestamp(end)-pd.Timestamp(start)).days/365.2425*12
  normalized.append(dict(window=name,return_pct=float(v.sum()/100),net_cash=float(v.sum()),pf=float(gp/gl),win_rate_pct=float((v>0).mean()*100),equity_dd_pct=r['metrics']['max_relative_equity_drawdown_pct'],trades=len(v),daily_sharpe=float(sh),max_win_streak=mw,max_loss_streak=ml,commission=float(d.commission.sum()),swap=float(d.swap.sum()),trades_month=len(v)/months,trades_weekday=len(v)/len(calendar),history_quality=r['metrics']['history_quality']))
 # Native primary equity. No random-control comparison is claimed on this graph.
 d=pd.DataFrame(json.loads((ROOT/'native/5y/trades.json').read_text()));dates=pd.to_datetime(d.close_time);eq=10000+d.net_profit.cumsum();peak=np.maximum.accumulate(np.r_[10000,eq.to_numpy()])[1:];dd=(peak-eq)/peak*100
 fig,(ax,bx)=plt.subplots(2,1,figsize=(12,7),gridspec_kw={'height_ratios':[3,1]},sharex=True)
 ax.plot(dates,eq,color='#66efc2',lw=1.5);ax.axhline(10000,color='#8eaaa0',lw=.7);ax.set_title('11:00–12:00 New York • native MT5 closing balance');ax.set_ylabel('USD • fixed 1 USTEC lot');ax.grid(alpha=.35)
 bx.fill_between(dates,-dd,0,color='#ff8b86',alpha=.65);bx.set_ylabel('Closed DD %');bx.grid(alpha=.35);fig.tight_layout();fig.savefig(ROOT/'native-11-equity.png',dpi=160);plt.close(fig)
 five=raw[raw.window=='5y'].sort_values('hour');fig,ax=plt.subplots(figsize=(12,4.5));colors=['#66efc2' if x>0 else '#ff8b86' for x in five.mean_net_points];ax.bar(five.hour,five.mean_net_points,color=colors);ax.axhline(0,color='#adbeb5',lw=.7);ax.set_xticks(range(24));ax.set_xlabel('New York entry hour');ax.set_ylabel('Mean net index points');ax.set_title('All-hour M1 approximation • spread included, commission/financing excluded');ax.grid(axis='y',alpha=.35);fig.tight_layout();fig.savefig(ROOT/'hour-means.png',dpi=160);plt.close(fig)
 r=np.load(ROOT/'random-curves.npz',allow_pickle=True);dt=pd.to_datetime(r['dates']);fig,ax=plt.subplots(figsize=(12,4.5));ax.fill_between(dt,r['q05'],r['q95'],color='#6c94a0',alpha=.3,label='Matched random pointwise 5–95% band');ax.plot(dt,r['median'],color='#7bb4c3',label='Random median');ax.plot(dt,r['observed'],color='#66efc2',label='11:00 bar approximation');ax.set_title('Bar-price screen only • 2,000 same-date random-minute paths');ax.set_ylabel('Cumulative USD • $1/index point');ax.legend(facecolor='#10271e',labelcolor='#e8f8ef');ax.grid(alpha=.3);fig.tight_layout();fig.savefig(ROOT/'random-comparison.png',dpi=160);plt.close(fig)
 ntable='<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in ['Window','Return','PF','Win rate','Equity DD','Trades','Daily Sharpe','Max W / L','Trades/month','Real-tick history'])+'</tr></thead><tbody>'
 md=['# US100 hourly raw test','', 'Primary result: 11:00–12:00 New York is weakly profitable, not a validated edge.','', 'Exness USTEC CFD; 2021-10-02 to 2026-10-02 exclusive. Fixed 1 lot, $10,000. No stop-loss. Native Model 4, 150ms. No live changes.','', '| Window | Return | PF | Win rate | Max equity DD | Trades | Daily Sharpe | Max W/L |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for z in normalized:
  cells=[z['window'],fmt(z['return_pct'])+'%',fmt(z['pf'],3),fmt(z['win_rate_pct'])+'%',fmt(z['equity_dd_pct'])+'%',str(z['trades']),fmt(z['daily_sharpe']),f"{z['max_win_streak']} / {z['max_loss_streak']}",fmt(z['trades_month']),z['history_quality']]
  ntable+='<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in cells)+'</tr>'
  md.append(f"|{z['window']}|{fmt(z['return_pct'])}%|{fmt(z['pf'],3)}|{fmt(z['win_rate_pct'])}%|{fmt(z['equity_dd_pct'])}%|{z['trades']}|{fmt(z['daily_sharpe'])}|{z['max_win_streak']}/{z['max_loss_streak']}|")
 ntable+='</tbody></table>'
 atable='<table><thead><tr><th>NY hour</th><th>Trades</th><th>Net pts/trade</th><th>Win rate</th><th>PF</th><th>Raw p</th><th>Adjusted p</th><th>UTC-midnight holds</th></tr></thead><tbody>'
 for z in five.itertuples():
  cells=[f'{z.hour:02}:00–{(z.hour+1)%24:02}:00',str(z.trades),fmt(z.mean_net_points,3),fmt(z.win_rate_pct)+'%',fmt(z.pf,3),fmt(z.p_raw,4),fmt(z.p_adjusted_maxT,4),str(z.utc_midnight_crossings)]
  atable+='<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in cells)+'</tr>'
 atable+='</tbody></table>'
